 * Longest common subsequence machinery for three-way merge.
 *
 * Given a base document and one other document (mine or theirs), compute a
 * specific canonical LCS: among all longest common subsequences, the one
 * whose matches come earliest is chosen, using the tie-break rule described
 * in the specification: walking both documents from the start, take a match
 * whenever the two current lines are equal, and otherwise advance the side
 * whose remaining subsequence (after skipping its current line) is at least
 * as long as the other's, preferring to advance the base on ties.
 */

/**
 * @param {string[]} base
 * @param {string[]} other
 * @returns {Array<[number, number]>} list of matched (baseIndex, otherIndex) pairs, increasing.
 */
export function lcsMatches(base, other) {
  const n = base.length
  const m = other.length

  // dp[i][j] = length of LCS of base[i:] and other[j:]
  const dp = new Array(n + 1)
  for (let i = 0; i <= n; i++) dp[i] = new Int32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      if (base[i] === other[j]) {
        dp[i][j] = dp[i + 1][j + 1] + 1
      } else {
        const a = dp[i + 1][j]
        const b = dp[i][j + 1]
        dp[i][j] = a > b ? a : b
      }
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === other[j]) {
      matches.push([i, j])
      i++
      j++
    } else {
      const skipBase = dp[i + 1][j]
      const skipOther = dp[i][j + 1]
      if (skipBase >= skipOther) {
        i++
      } else {
        j++
      }
    }
  }
  return matches
}

/**
 * Turn a match list into the runs of change between them: every stretch of
 * base lines not covered by a match, paired with the corresponding stretch
 * of the other document's lines.
 *
 * @param {string[]} base
 * @param {string[]} other
 * @param {Array<[number, number]>} matches
 * @param {'mine'|'theirs'} side
 */
export function buildChanges(base, other, matches, side) {
  const changes = []
  let pi = 0
  let pj = 0
  for (const [i, j] of matches) {
    if (i > pi || j > pj) {
      changes.push({ side, baseStart: pi, baseEnd: i, otherStart: pj, otherEnd: j })
    }
    pi = i + 1
    pj = j + 1
  }
  if (pi < base.length || pj < other.length) {
    changes.push({ side, baseStart: pi, baseEnd: base.length, otherStart: pj, otherEnd: other.length })
  }
  return changes
}
"}

