{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e1-sonnet-vs-opus-t5/cell-K916Ne/src/diff3.js","content":"/**
 * Three-way merge over whole lines, following the region-based algorithm
 * described in the specification.
 */

import { lcsMatches, buildChanges } from './lcs.js'

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return false
  }
  return true
}

// Merge two lists, each already sorted ascending by baseStart, keeping mine
// before theirs when their baseStart values tie.
function mergeChangeLists(mineChanges, theirsChanges) {
  const result = []
  let i = 0
  let j = 0
  while (i < mineChanges.length && j < theirsChanges.length) {
    if (mineChanges[i].baseStart <= theirsChanges[j].baseStart) {
      result.push(mineChanges[i++])
    } else {
      result.push(theirsChanges[j++])
    }
  }
  while (i < mineChanges.length) result.push(mineChanges[i++])
  while (j < theirsChanges.length) result.push(theirsChanges[j++])
  return result
}

// Group changes into regions: absorb any change whose baseStart falls at or
// before the region's current end, extending the end to cover it.
function buildChangeRegions(allChanges) {
  const regions = []
  let i = 0
  while (i < allChanges.length) {
    const first = allChanges[i]
    const region = { baseStart: first.baseStart, baseEnd: first.baseEnd, changes: [first] }
    i++
    while (i < allChanges.length && allChanges[i].baseStart <= region.baseEnd) {
      const c = allChanges[i]
      if (c.baseEnd > region.baseEnd) region.baseEnd = c.baseEnd
      region.changes.push(c)
      i++
    }
    regions.push(region)
  }
  return regions
}

// Map a base-document boundary index (guaranteed to sit outside every change
// in `sideChanges`) to the corresponding index in that side's own document.
function sideIndexForBoundary(sideChanges, baseIndex) {
  let offset = 0
  for (const c of sideChanges) {
    if (c.baseEnd <= baseIndex) {
      offset += (c.otherEnd - c.otherStart) - (c.baseEnd - c.baseStart)
    }
  }
  return baseIndex + offset
}

/**
 * Compute the full list of blocks describing the merge: stable stretches of
 * base lines, and regions touched by one or more changes with their
 * resolution.
 *
 * @param {string[]} mine
 * @param {string[]} base
 * @param {string[]} theirs
 */
export function diff3(mine, base, theirs) {
  const mineMatches = lcsMatches(base, mine)
  const theirsMatches = lcsMatches(base, theirs)
  const mineChanges = buildChanges(base, mine, mineMatches, 'mine')
  const theirsChanges = buildChanges(base, theirs, theirsMatches, 'theirs')
  const allChanges = mergeChangeLists(mineChanges, theirsChanges)
  const changeRegions = buildChangeRegions(allChanges)

  const blocks = []
  let pos = 0
  for (const region of changeRegions) {
    if (region.baseStart > pos) {
      blocks.push({ type: 'stable', lines: base.slice(pos, region.baseStart) })
    }

    const mineStart = sideIndexForBoundary(mineChanges, region.baseStart)
    const mineEnd = sideIndexForBoundary(mineChanges, region.baseEnd)
    const theirsStart = sideIndexForBoundary(theirsChanges, region.baseStart)
    const theirsEnd = sideIndexForBoundary(theirsChanges, region.baseEnd)

    const mineLines = mine.slice(mineStart, mineEnd)
    const theirsLines = theirs.slice(theirsStart, theirsEnd)
    const baseLines = base.slice(region.baseStart, region.baseEnd)

    let kind
    let resolved
    if (arraysEqual(mineLines, theirsLines)) {
      kind = 'both'
      resolved = mineLines
    } else if (arraysEqual(mineLines, baseLines)) {
      kind = 'theirs'
      resolved = theirsLines
    } else if (arraysEqual(theirsLines, baseLines)) {
      kind = 'mine'
      resolved = mineLines
    } else {
      kind = 'conflict'
      resolved = null
    }

    blocks.push({ type: 'region', kind, mineLines, baseLines, theirsLines, resolved })
    pos = region.baseEnd
  }
  if (pos < base.length) {
    blocks.push({ type: 'stable', lines: base.slice(pos, base.length) })
  }

  return blocks
}
"}

