/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { diff3 } from './diff3.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function splitDocuments(input) {
  let lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines = lines.slice(0, -1)
  }

  const docs = [[]]
  for (const line of lines) {
    if (line === '%%%') {
      docs.push([])
    } else {
      docs[docs.length - 1].push(line)
    }
  }

  if (docs.length !== 3) {
    return null
  }
  return docs
}

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (chunk) => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

function renderMerge(blocks, withBase) {
  const out = []
  let conflict = false
  for (const block of blocks) {
    if (block.type === 'stable') {
      for (const line of block.lines) out.push(line)
    } else if (block.kind === 'conflict') {
      conflict = true
      out.push('<<<<<<< mine')
      for (const line of block.mineLines) out.push(line)
      if (withBase) {
        out.push('||||||| base')
        for (const line of block.baseLines) out.push(line)
      }
      out.push('=======')
      for (const line of block.theirsLines) out.push(line)
      out.push('>>>>>>> theirs')
    } else {
      for (const line of block.resolved) out.push(line)
    }
  }
  const text = out.length > 0 ? out.join('\n') + '\n' : ''
  return { text, conflict }
}

function renderRegions(blocks) {
  const out = []
  let conflict = false
  for (const block of blocks) {
    if (block.type === 'stable') {
      out.push(`stable ${block.lines.length}`)
    } else if (block.kind === 'conflict') {
      conflict = true
      out.push(`conflict mine=${block.mineLines.length} base=${block.baseLines.length} theirs=${block.theirsLines.length}`)
    } else {
      out.push(`${block.kind} ${block.resolved.length}`)
    }
  }
  const text = out.length > 0 ? out.join('\n') + '\n' : ''
  return { text, conflict }
}

async function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || !MODES.has(mode)) {
    fail('usage: cli.js merge|merge2|regions')
    return
  }

  const input = await readStdin()
  const docs = splitDocuments(input)
  if (docs === null) {
    fail('expected three parts separated by %%%')
    return
  }

  const [mine, base, theirs] = docs
  const blocks = diff3(mine, base, theirs)

  let result
  if (mode === 'merge') {
    result = renderMerge(blocks, true)
  } else if (mode === 'merge2') {
    result = renderMerge(blocks, false)
  } else {
    result = renderRegions(blocks)
  }

  process.stdout.write(result.text)
  process.exit(result.conflict ? 1 : 0)
}

main()
