// in `sideChanges`) to the corresponding index in that side's own document.
//
// A zero-width (pure insertion) change has baseStart === baseEnd, which
// makes it sit exactly on a boundary index. When that boundary is the start
// of a region, such a change belongs *after* it (it is the first change of
// the region); when the boundary is the end of a region, it belongs
// *before* it (it is the last change of the region). The two boundary kinds
// therefore need different inclusion tests.
function sideIndexBeforeBoundary(sideChanges, baseIndex) {
  let offset = 0
  for (const c of sideChanges) {
    if (c.baseStart < baseIndex) {
      offset += (c.otherEnd - c.otherStart) - (c.baseEnd - c.baseStart)
    }
  }
  return baseIndex + offset
}

function sideIndexAfterBoundary(sideChanges, baseIndex) {
  let offset = 0
  for (const c of sideChanges) {
    if (c.baseEnd <= baseIndex) {
      offset += (c.otherEnd - c.otherStart) - (c.baseEnd - c.baseStart)
    }

