// deletion at start
console.log('delStart', JSON.stringify(run(['merge'], ['b'], ['a','b'], ['a','b'])))

// conflict with different sizes
console.log('conflictSizes', JSON.stringify(run(['regions'], ['a','X1','X2','c'], ['a','b','c'], ['a','Y','c'])))
EOF
